attributes.onChange:
{(e) => {
                      const file = e.target.files?.[0];
                      if (!file) return;
                      if (file.size > 24576) {
                        setError("Uploads are limited to 24 KiB text files.");
                        return;
                      }
                      void file
                        .text()
                        .then((text) =>
                          props.run(
                            "files.upload",
                            {
                              root,
                              path: (path ? path + "/" : "") + file.name,
                              content: text,
                            },
                            kind,
                          ),
                        )
                        .then(() => listing.refresh())
                        .catch(() => {});
                      e.target.value = "";
                    }}

attributes.onClick:
{async () => {
                      controller.current = new AbortController();
                      setDownload(0);
                      try {
                        await downloadTransfer(
                          "files.download",
                          { root, path: selected.path },
                          selected.path.split("/").at(-1)!,
                          kind,
                          controller.current.signal,
                          setDownload,
                          props.state.serverId,
                        );
                        props.notice("Download verified with SHA-256.");
                      } catch (e) {
                        setError(
                          e instanceof Error ? e.message : "Download failed",
                        );
                      } finally {
                        setDownload(null);
                      }
                    }}

